// Generated by esquadro: do not edit. A question before what cannot be
// undone, in shadcn/ui's AlertDialog: await ask("Delete it?").
import { CircleAlert, CircleCheck, Info, TriangleAlert, type IconComponent } from "../icons.gen.ts"
import { useEffect, useState } from "react"
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog"
import { cn } from "@/lib/utils"
import { t } from "./i18n.ts"

/** What a question is about, which gives its icon and color. */
export type AskKind = "info" | "success" | "warning" | "danger"

/** Each kind's icon, in a circle of its color. */
const KINDS: Record<AskKind, { icon: IconComponent; className: string }> = {
  info: { icon: Info, className: "bg-blue-100 text-blue-600 dark:bg-blue-500/20 dark:text-blue-100" },
  success: { icon: CircleCheck, className: "bg-emerald-100 text-emerald-600 dark:bg-emerald-500/20 dark:text-emerald-100" },
  warning: { icon: CircleAlert, className: "bg-amber-100 text-amber-600 dark:bg-amber-500/20 dark:text-amber-100" },
  danger: { icon: TriangleAlert, className: "bg-red-100 text-red-600 dark:bg-red-500/20 dark:text-red-100" },
}

export interface AskOptions {
  /** info by default; danger when destructive. */
  kind?: AskKind
  /** What removes or cannot be undone: a danger. */
  destructive?: boolean
  /** More than the question: what will happen. */
  description?: string
  /** The button that says yes (Yes by default). */
  confirm?: string
}

type Question = AskOptions & { text: string; answer: (yes: boolean) => void }
let show: ((q: Question) => void) | undefined

/** Asks a yes or no question; true on yes. */
export function ask(text: string, options: AskOptions = {}): Promise<boolean> {
  return new Promise((answer) => {
    if (!show) return answer(false)
    show({ ...options, text, answer })
  })
}

/** Where the questions appear: once, in src/pages/__root.tsx. */
export function Confirmer() {
  const [question, setQuestion] = useState<Question | null>(null)
  const [open, setOpen] = useState(false)
  useEffect(() => {
    show = (q) => {
      setQuestion(q)
      setOpen(true)
    }
    return () => {
      show = undefined
    }
  }, [])
  const answer = (yes: boolean) => {
    setOpen(false)
    question?.answer(yes)
  }
  const kind = KINDS[question?.kind ?? (question?.destructive ? "danger" : "info")]
  return (
    <AlertDialog open={open} onOpenChange={(o) => !o && answer(false)}>
      <AlertDialogContent className="gap-0 overflow-hidden p-0 sm:max-w-md">
        <div className="flex gap-4 px-6 pt-6 pb-6">
          <div className={cn("flex size-12 shrink-0 items-center justify-center rounded-full", kind.className)}>
            <kind.icon className="size-6" />
          </div>
          <div className="flex min-w-0 flex-col gap-2 pt-0.5 text-left">
            <AlertDialogTitle className="text-lg font-bold">{question?.text}</AlertDialogTitle>
            <AlertDialogDescription className={cn(!question?.description && "sr-only")}>
              {question?.description ?? question?.text}
            </AlertDialogDescription>
          </div>
        </div>
        {/* The answers, in a band of their own. */}
        <div className="flex justify-end gap-2 bg-muted px-6 py-3">
          <AlertDialogCancel size="sm" onClick={() => answer(false)}>
            {t("cancel")}
          </AlertDialogCancel>
          <AlertDialogAction size="sm" onClick={() => answer(true)}>
            {question?.confirm ?? t("yes")}
          </AlertDialogAction>
        </div>
      </AlertDialogContent>
    </AlertDialog>
  )
}
